-- Aditivo e idempotente: preserva inventários e itens existentes.
on conflict (id) do update set name=excluded.name,slot=excluded.slot,rarity=excluded.rarity,icon=excluded.icon,description=excluded.description,asset_key=excluded.asset_key,unlock_type=excluded.unlock_type,price=excluded.price,achievement_id=excluded.achievement_id,active=true;